package com.smartrecruit.identity.api;
import com.smartrecruit.identity.domain.UserAccount; import com.smartrecruit.identity.repo.UserRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.authentication.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.oauth2.jose.jws.MacAlgorithm; import org.springframework.security.oauth2.jwt.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController public class IdentityController { private final UserRepository repo;private final PasswordEncoder passwords;private final AuthenticationManager auth;private final JwtEncoder jwt;@Value("${identity.jwt.issuer}")String issuer; public IdentityController(UserRepository r,PasswordEncoder p,AuthenticationManager a,JwtEncoder j){repo=r;passwords=p;auth=a;jwt=j;}
 public record Register(@Email @NotBlank String email,@Size(min=12,max=72)String password,@NotBlank String fullName,String phone,String address,String city,String country){} public record Login(@Email String email,String password){} public record Token(String accessToken,String tokenType,long expiresIn){}
 @PostMapping("/api/v1/auth/register/candidate")@ResponseStatus(HttpStatus.CREATED)@Transactional public UserAccount candidate(@Valid@RequestBody Register d){return create(d,UserAccount.Role.CANDIDATE,UserAccount.Status.ACTIVE);}
 @PostMapping("/api/v1/auth/register/recruiter")@ResponseStatus(HttpStatus.CREATED)@Transactional public UserAccount recruiter(@Valid@RequestBody Register d){return create(d,UserAccount.Role.RECRUITER,UserAccount.Status.PENDING);}
 private UserAccount create(Register d,UserAccount.Role role,UserAccount.Status status){if(repo.existsByEmailIgnoreCase(d.email()))throw new IllegalArgumentException("Email already registered");var u=new UserAccount();u.email=d.email().trim().toLowerCase();u.passwordHash=passwords.encode(d.password());u.fullName=d.fullName();u.phone=d.phone();u.address=d.address();u.city=d.city();u.country=d.country();u.role=role;u.status=status;return repo.save(u);}
 @PostMapping("/api/v1/auth/login") public Token login(@Valid@RequestBody Login d){auth.authenticate(new UsernamePasswordAuthenticationToken(d.email(),d.password()));var u=repo.findByEmailIgnoreCase(d.email()).orElseThrow();var now=Instant.now();var claims=JwtClaimsSet.builder().issuer(issuer).subject(u.email).issuedAt(now).expiresAt(now.plusSeconds(3600)).claim("user_id",u.id.toString()).claim("roles",List.of(u.role.name())).build();var t=jwt.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),claims)).getTokenValue();return new Token(t,"Bearer",3600);}
 @GetMapping("/api/v1/users/me") public UserAccount me(Authentication a){return repo.findByEmailIgnoreCase(a.getName()).orElseThrow();}
 @GetMapping("/api/v1/admin/users")@PreAuthorize("hasRole('PLATFORM_ADMINISTRATOR')") public List<UserAccount> all(){return repo.findAll();}
 @PostMapping("/api/v1/admin/recruiters/{id}/approve")@PreAuthorize("hasRole('PLATFORM_ADMINISTRATOR')")@Transactional public UserAccount approve(@PathVariable UUID id){var u=repo.findById(id).orElseThrow();u.status=UserAccount.Status.ACTIVE;return u;}
 @PostMapping("/api/v1/admin/recruiters/{id}/reject")@PreAuthorize("hasRole('PLATFORM_ADMINISTRATOR')")@Transactional public UserAccount reject(@PathVariable UUID id){var u=repo.findById(id).orElseThrow();u.status=UserAccount.Status.REJECTED;return u;}
}
